        #region BackFlush

        public bool SendToBackFlush(WorkOrderCompletion wo)
        {
            SqlConnection cnJDE = new SqlConnection(GetConnectionString());
            SqlCommand cmd = new SqlCommand("sp_WorkOrderBackFlush", cnJDE);
            cmd.Parameters.Add("@WorkOrder", SqlDbType.VarChar, 50).Value = wo.WorkOrder;
            cmd.Parameters.Add("@WorkOrderType", SqlDbType.VarChar, 10).Value = wo.WOType;
            cmd.Parameters.Add("@Batch", SqlDbType.VarChar, 50).Value = wo.Batch;
            cmd.Parameters.Add("@CDate", SqlDbType.Int).Value = wo.CDate;
            cmd.Parameters.Add("@CTime", SqlDbType.Int).Value = wo.CTime;
            cmd.Parameters.Add("@Part", SqlDbType.VarChar, 50).Value = wo.Part;
            //cmd.Parameters.Add("@Branch", SqlDbType.VarChar, 50).Value = wo.Branch;
            cmd.Parameters.Add("@BoxQty", SqlDbType.Int).Value = wo.BoxQty;
            cmd.Parameters.Add("@StationID", SqlDbType.Int).Value = wo.StationID;
            cmd.Parameters.Add("@Location", SqlDbType.VarChar, 50).Value = wo.Location;
            cmd.Parameters.Add("@Shift", SqlDbType.VarChar, 50).Value = wo.Shift;
            cmd.Parameters.Add("@ClockNumber", SqlDbType.VarChar, 50).Value = "";
            cmd.Parameters.Add("@LotNumber", SqlDbType.VarChar, 50).Value = wo.LotNumber;
            cmd.Parameters.Add("@SerialNumber", SqlDbType.VarChar, 50).Value = wo.SerialNumber;
            cmd.Parameters.Add("@ProcessID", SqlDbType.VarChar, 50).Value = wo.ProcessID;
            cmd.Parameters.Add("@UserID", SqlDbType.VarChar, 50).Value = wo.UserID;
            cmd.Parameters.Add("@TypeFlag", SqlDbType.Int).Value = wo.TypeFlag;
            cmd.Parameters.Add("@ScrapQty", SqlDbType.Int).Value = double.Parse(wo.ScrapQty) * 100000;
            cmd.Parameters.Add("@ScrapSeq", SqlDbType.Int).Value = double.Parse(wo.ScrapSeq) * 100;
            cmd.Parameters.Add("@F4801Z1", SqlDbType.Int).Value = wo.F4801Z1;
            cmd.CommandType = CommandType.StoredProcedure;
            try
            {
                cnJDE.Open();
                Log.Debug($"<***> Inserting BackFlush Data");
                SqlDataReader drJDE = cmd.ExecuteReader();
                while(drJDE.Read())
                {
                    if (drJDE["done"].ToString() != "0")
                    {
                        Log.Debug($"<***> {drJDE["done"]} {drJDE["message"]}");
                        return false;
                    }
                }
                cnJDE.Close();
            }
            catch(Exception ex)
            { 
                Log.Debug($"<***> Exception caught: {ex.Message}");
                foreach(SqlParameter par in cmd.Parameters)
                {
                    Log.Debug($"<***> {par.ParameterName} = {par.Value}");
                }
                return false;
            }
            finally
            {
                cnJDE.Close();
            }

            return true;
        }

